"""Validate actual PDFs generated by compact_print_browser_test.cjs --letterhead."""
from pathlib import Path

import fitz

root = Path(__file__).resolve().parent.parent / '.local/monitoring-review'
for orientation in ['portrait', 'landscape']:
    with fitz.open(root / f'letterhead-{orientation}.pdf') as document:
        assert len(document) > 2, 'Need table continuation pages to verify repetition'
        for number, page in enumerate(document, 1):
            text = page.get_text()
            assert text.count('HASIL PELAPORAN PROFIL RISIKO') == 1, (orientation, number)
            assert text.count('Jl. Tanjung') == 1, (orientation, number)
            assert 'Jenis Profil Risiko' not in text and 'Tanggal Cetak' not in text
            words = page.get_text('words')
            header_words = [word for word in words if word[1] < 100]
            assert any('PELAPORAN' == word[4] for word in header_words)
            assert all(20 <= word[0] < word[2] <= page.rect.width - 20 for word in header_words)
            # Letterhead ends at the double rule; report content starts below it.
            body_words = [word for word in words if word not in header_words]
            assert body_words and min(word[1] for word in body_words) > 105, (orientation, number)
        if orientation == 'portrait':
            first = document[0].get_text()
            assert 'URAIAN PROFIL RISIKO' in first
            assert 'Penyusunan Laporan' in first, 'Opening narrative moved off the first page'
        for index in [0, 1, len(document) - 1]:
            document[index].get_pixmap(matrix=fitz.Matrix(1, 1)).save(root / f'letterhead-{orientation}-{index + 1}.png')
        print(f'PASS {orientation}: letterhead and address above content on all {len(document)} pages; no empty pages')
